#include <cmath>
#include <array>

bool areOrthogonal(const std::array<double, 3>& u, const std::array<double, 3>& v, double eps = 1e-7) {
    double dot = u[0]*v[0] + u[1]*v[1] + u[2]*v[2];
    double mag = std::sqrt((u[0]*u[0]+u[1]*u[1]+u[2]*u[2]) * (v[0]*v[0]+v[1]*v[1]+v[2]*v[2]));
    return mag > eps && (std::abs(dot) / mag) <= eps;
}

bool areParallel(const std::array<double, 3>& u, const std::array<double, 3>& v, double eps = 1e-7) {
    std::array<double, 3> cross = { u[1]*v[2] - u[2]*v[1], u[2]*v[0] - u[0]*v[2], u[0]*v[1] - u[1]*v[0] };
    double crossSq = cross[0]*cross[0] + cross[1]*cross[1] + cross[2]*cross[2];
    double magSq = (u[0]*u[0]+u[1]*u[1]+u[2]*u[2]) * (v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);
    return magSq > eps && (crossSq / magSq) <= eps * eps;
}

