bool areCoplanar(const double u[3], const double v[3], const double w[3], double eps = 1e-6) {
    double cross[3] = { v[1]*w[2] - v[2]*w[1], v[2]*w[0] - v[0]*w[2], v[0]*w[1] - v[1]*w[0] };
