    int n = poly.size();
    if (n < 3) return false;
    int sign = 0;
    for (int i = 0; i < n; ++i) {
        const auto& p0 = poly[(i + n - 1) % n];
        const auto& p1 = poly[i];
        const auto& p2 = poly[(i + 1) % n];
        double cp = (p1.x - p0.x) * (p2.y - p1.y) - (p1.y - p0.y) * (p2.x - p1.x);
