def point_to_line_dist(q, p0, d):
    v = [q[i] - p0[i] for i in range(3)]
    cross = [v[1]*d[2]-v[2]*d[1], v[2]*d[0]-v[0]*d[2], v[0]*d[1]-v[1]*d[0]]
