def point_to_segment_dist(q, a, b):
    d = [b[i] - a[i] for i in range(3)]
    v = [q[i] - a[i] for i in range(3)]
    d_sq = sum(di * di for di in d)
    if d_sq < 1e-12: return math.sqrt(sum(vi * vi for vi in v))
    t = max(0.0, min(1.0, sum(vi * di for vi, di in zip(v, d)) / d_sq))
    closest = [a[i] + t * d[i] for i in range(3)]
    return math.sqrt(sum((q[i] - closest[i])**2 for i in range(3)))

