#include <cmath>
#include <algorithm>

double pointToSegmentDist(const double q[3], const double a[3], const double b[3]) {
    double d[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] };
    double v[3] = { q[0] - a[0], q[1] - a[1], q[2] - a[2] };
    double dSq = d[0]*d[0] + d[1]*d[1] + d[2]*d[2];
    double t = (dSq < 1e-12) ? 0.0 : std::clamp((v[0]*d[0] + v[1]*d[1] + v[2]*d[2]) / dSq, 0.0, 1.0);
    double distSq = 0.0;
    for (int i = 0; i < 3; ++i) {
        double diff = q[i] - (a[i] + t * d[i]);
        distSq += diff * diff;
    }
    return std::sqrt(distSq);
}

