        (v[1]*d[2] - v[2]*d[1]) / dLenSq,
        (v[2]*d[0] - v[0]*d[2]) / dLenSq,
        (v[0]*d[1] - v[1]*d[0]) / dLenSq
    };
    return Line3D{p0, d};
}

