#include <optional>
#include <utility>

struct Point2D { double x, y; };
std::optional<std::pair<Point2D, double>> circleFrom3Points(Point2D a, Point2D b, Point2D c) {
    double d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    if (std::abs(d) < 1e-10) return std::nullopt;
    double aSq = a.x*a.x + a.y*a.y, bSq = b.x*b.x + b.y*b.y, cSq = c.x*c.x + c.y*c.y;
    double ux = (aSq * (b.y - c.y) + bSq * (c.y - a.y) + cSq * (a.y - b.y)) / d;
    double uy = (aSq * (c.x - b.x) + bSq * (a.x - c.x) + cSq * (b.x - a.x)) / d;
    double r = std::hypot(a.x - ux, a.y - uy);
    return std::make_pair(Point2D{ux, uy}, r);
}

