import math

def min_enclosing_circle_radius(a: float, b: float, c: float, angles_deg: tuple[float, float, float]) -> float:
    # Check if any angle >= 90 degrees
    if any(angle >= 90.0 for angle in angles_deg):
        return max(a, b, c) / 2.0
    # Acute triangle: Circumradius via Sine Law
    max_angle_idx = angles_deg.index(max(angles_deg))
    sides = [a, b, c]
    return sides[max_angle_idx] / (2.0 * math.sin(math.radians(angles_deg[max_angle_idx])))

