double minEnclosingCircleRadius(double a, double b, double c, double A_rad, double B_rad, double C_rad) {
    const double halfPi = 1.5707963267948966;
    if (A_rad >= halfPi || B_rad >= halfPi || C_rad >= halfPi) {
        return std::max({a, b, c}) * 0.5;
    }
    return a / (2.0 * std::sin(A_rad));
}

