#include <array>

// Point P_cs2 = M2_inv * M1 * P_cs1
std::array<double, 3> transformBetweenCS(
    const std::array<double, 3>& pCS1,
    const double M1[4][4],
    const double M2_inv[4][4]
) {
    double mRel[4][4] = {0};
    for (int i = 0; i < 4; ++i)
        for (int j = 0; j < 4; ++j)
            for (int k = 0; k < 4; ++k)
                mRel[i][j] += M2_inv[i][k] * M1[k][j];

    double pHomo[4] = { pCS1[0], pCS1[1], pCS1[2], 1.0 };
    std::array<double, 3> result;
    for (int i = 0; i < 3; ++i) {
        result[i] = mRel[i][0]*pHomo[0] + mRel[i][1]*pHomo[1] + mRel[i][2]*pHomo[2] + mRel[i][3]*pHomo[3];
    }
    return result;
}

