public static double[] TransformPointCS1ToCS2(double[] pCS1, double[,] m1, double[,] m2Inv) {
    // Relative matrix M_rel = M2_inv * M1
    double[,] mRel = new double[4, 4];
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            for (int k = 0; k < 4; k++)
                mRel[i, j] += m2Inv[i, k] * m1[k, j];
    double[] res = new double[3];
    for (int i = 0; i < 3; i++) {
        res[i] = mRel[i, 0]*pCS1[0] + mRel[i, 1]*pCS1[1] + mRel[i, 2]*pCS1[2] + mRel[i, 3]*1.0;
    }
    return res;
}
